def is_samepatterns(sequence, patterns):
    """
    Return True if the given sequence follows the equality pattern
    described by the patterns array.

    Positions with the same pattern element must have the same sequence
    element, and positions with different pattern elements must have
    different sequence elements.
    """
    if len(sequence) != len(patterns):
        return False

    value_to_pattern = {}
    pattern_to_value = {}

    for value, pattern in zip(sequence, patterns):
        if pattern in pattern_to_value:
            if pattern_to_value[pattern] != value:
                return False
        else:
            pattern_to_value[pattern] = value

        if value in value_to_pattern:
            if value_to_pattern[value] != pattern:
                return False
        else:
            value_to_pattern[value] = pattern

    return True


